{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Currently, there is no clarity regarding the prevalence of SARS-CoV-2 infection among HCWs according to specific clinical settings, limiting the possibility of designing effective preventive measures to limit the transmission of the virus within a hospital, and from hospitals to the community (9, 10). Furthermore, it is unknown whether the clinical characteristics and outcomes of HCWs may be different from those of the general population, considering that the repeated exposure to the virus may lead to higher SARS-CoV2 viral load and, therefore, to worse clinical outcomes (11, 12).",
      "reason": "The introduction describes existing gaps/uncertainties about (1) prevalence by clinical settings and (2) whether clinical characteristics/outcomes differ from the general population."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Therefore, characterizing SARS-CoV-2 infection within HCWs is critical for achieving optimal control of the pandemic. With the present systematic review and meta-analysis, we aimed to identify, analyze, and quantify the prevalence, risk factors, clinical characteristics, and outcomes of COVID-19 among HCWs.",
      "reason": "The importance/need is explained as being critical for pandemic control, and it states the review’s purpose to quantify prevalence, risk factors, clinical characteristics, and outcomes."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not explain the need for a current review in the context of similar systematic reviews, nor does it identify/cite previous systematic reviews to justify updates or replications."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a prevalence/risk factors/clinical characteristics/outcomes synthesis rather than a review of intervention effects; therefore, a mechanism of action for an intervention is not applicable based on the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence describes a systematic review and meta-analysis of prevalence/risk factors/outcomes, not a complex intervention or delivery context; thus, a logic model is not applicable based on the retrieved evidence."
    }
  ],
  "confidence": 74
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_1",
      "quote": "Therefore, characterizing SARS-CoV-2 infection within HCWs is critical for achieving optimal control of the pandemic. With the present systematic review and meta-analysis, we aimed to identify, analyze, and quantify the prevalence, risk factors, clinical characteristics, and outcomes of COVID-19 among HCWs.",
      "reason": "The review’s objective is explicitly stated (“we aimed to identify, analyze, and quantify…”). However, the evidence provided does not show that the objective/questions are formulated using a relevant question-formulation framework."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence describes a systematic review/meta-analysis of prevalence, risk factors, clinical characteristics, and outcomes of COVID-19 among health-care workers, not planned intervention effect comparisons. Therefore, stating planned comparisons using PICO (or variant) is not applicable based on the provided evidence."
    }
  ],
  "confidence": 72
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "All observational studies (eg, cross-sectional, cohort, case-control studies, and case series) except for case reports were included. We included studies that reported the prevalence of COVID-19 in HCWs, using either reverse transcription-polymerase chain reaction (RT-PCR) or a serum antibodies assay. We also included studies evaluating the risk factors for SARS-CoV-2 infection and those analyzing the clinical characteristics and outcomes of laboratory-confirmed COVID-19 among HCWs. We excluded those articles that evaluated HCWs with suspected but not laboratory-confirmed SARS-CoV-2 infection.",
      "reason": "Eligibility-specific study characteristics are described (eligible observational study designs, HCW population, required outcome/assessment via RT-PCR or antibodies, and exclusion for suspected/unconfirmed SARS-CoV-2). However, evidence does not specify relevant question-framework components comprehensively (eg, settings and follow-up requirements are not clearly stated)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Medline, Embase, Latin American and Caribbean Health Sciences Literature (LILACS), Cochrane, Web of Science, the World Health Organization COVID-19 database, Google Scholar, and Living Evidence on COVID-19, a database developed by the Institute of Social and Preventive Medicine, University of Bern, were searched to identify relevant articles from inception until July 8, 2020, without language restrictions.",
      "reason": "Report characteristics related to language restrictions and search time window are stated, but dissemination year eligibility and publication/report status criteria are not fully specified in the retrieved evidence (other than mention that included studies were all published in 2020, without full criteria for publication status)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not report a distinction between exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Screening criteria, geographic location, HCW professions, the clinical setting, and the mean of daily new cases of SARS-CoV-2 per million inhabitants (15) in the country during the period in which the study was carried out were prespecified as characteristics for assessment of heterogeneity and were evaluated using stratified analyses and univariate random-effects meta-regression.",
      "reason": "The evidence specifies characteristics used for stratified analyses/meta-regression (i.e., groups used across syntheses). However, it does not explicitly link these groups to the specific comparisons/objectives defined in the review."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No rationale is provided in the retrieved evidence for notable restrictions on study eligibility."
    }
  ],
  "confidence": 62
}

